#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

i128 nCr2(int64 n) {
    return static_cast<i128>(n) * (n - 1) / 2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m;
    cin >> n >> m;

    int64 maximum = 0;
    int64 minimum = 0;

    if (n != 1 && m != 0) {
        int64 left = 2, right = n - 1;

        while (left <= right) {
            int64 mid = left + (right - left) / 2;
            if (nCr2(mid) >= m) {
                maximum = n - mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        if (maximum != 0) {
            long double answer =
                static_cast<long double>(n) /
                (2.0L * static_cast<long double>(m));

            if (answer > 1.0L)
                minimum = static_cast<int64>(answer);
        }

        cout << minimum << ' ' << maximum << '\n';
    } else {
        cout << n << ' ' << n << '\n';
    }

    return 0;
}

